//! vchiq.resource's functions: the message queue the VideoCore's firmware
//! keeps with the ARM, its services opened by name, their messages and
//! bulk transfers (sdk/resources/vchiq.zig). A resource: no Open or
//! Close, its first function in the first slot. The base comes from
//! OpenResource("vchiq.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/vchiq_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const vchiq = @import("../resources/vchiq.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "vchiq.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const OpenService = libraries.lvo(0);
    pub const CloseService = libraries.lvo(1);
    pub const SendMessage = libraries.lvo(2);
    pub const ReceiveMessage = libraries.lvo(3);
    pub const QueueBulk = libraries.lvo(4);
    pub const WaitBulk = libraries.lvo(5);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OpenService = *const fn (*VchiqBase, u32, u32, u32, ?*u32) callconv(.c) ?*vchiq.VchiqService;
    pub const CloseService = *const fn (*VchiqBase, ?*vchiq.VchiqService) callconv(.c) void;
    pub const SendMessage = *const fn (*VchiqBase, *vchiq.VchiqService, [*]const u8, u32) callconv(.c) u32;
    pub const ReceiveMessage = *const fn (*VchiqBase, *vchiq.VchiqService, [*]u8, u32, *u32, u64) callconv(.c) u32;
    pub const QueueBulk = *const fn (*VchiqBase, *vchiq.VchiqService, *vchiq.VchiqBulk) callconv(.c) u32;
    pub const WaitBulk = *const fn (*VchiqBase, *vchiq.VchiqBulk, u64) callconv(.c) u32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const VchiqBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *VchiqBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The firmware's service `fourcc` (vchiq.fourcc), for a caller who
    /// speaks `version` of its protocol and nothing below `version_min`; the
    /// first connects with the firmware. Null, and why in `err` (VCHIQERR_*),
    /// when it failed.
    pub fn OpenService(self: *VchiqBase, fourcc: u32, version: u32, version_min: u32, err: ?*u32) ?*vchiq.VchiqService {
        return libraries.call(self, LVO.OpenService, Fn.OpenService, .{ fourcc, version, version_min, err });
    }

    /// The service closed, what came for it and was not received with it.
    pub fn CloseService(self: *VchiqBase, service: ?*vchiq.VchiqService) void {
        return libraries.call(self, LVO.CloseService, Fn.CloseService, .{service});
    }

    /// `size` bytes sent as one message, after those sent before:
    /// VCHIQERR_OK, or why not. Waits while the queue is full.
    pub fn SendMessage(self: *VchiqBase, service: *vchiq.VchiqService, data: [*]const u8, size: u32) u32 {
        return libraries.call(self, LVO.SendMessage, Fn.SendMessage, .{ service, data, size });
    }

    /// The next message from the firmware into `buffer`, `size` bytes of
    /// room, waiting up to `timeout_us` for one; its length in `length`, of
    /// which no more than `size` was copied. VCHIQERR_OK, VCHIQERR_TIMEOUT,
    /// or VCHIQERR_CLOSED once the service is closed and nothing is left.
    pub fn ReceiveMessage(self: *VchiqBase, service: *vchiq.VchiqService, buffer: [*]u8, size: u32, length: *u32, timeout_us: u64) u32 {
        return libraries.call(self, LVO.ReceiveMessage, Fn.ReceiveMessage, .{ service, buffer, size, length, timeout_us });
    }

    /// `bulk` put out for the firmware, after those of its direction already
    /// out: VCHIQERR_OK, and `bulk.done` is signalled when it is done; or why
    /// not, and nothing was put out.
    pub fn QueueBulk(self: *VchiqBase, service: *vchiq.VchiqService, bulk: *vchiq.VchiqBulk) u32 {
        return libraries.call(self, LVO.QueueBulk, Fn.QueueBulk, .{ service, bulk });
    }

    /// Wait up to `timeout_us` for `bulk` to be done: its result
    /// (VCHIQERR_OK, VCHIQERR_ABORTED), or VCHIQERR_TIMEOUT - and then it is
    /// still out.
    pub fn WaitBulk(self: *VchiqBase, bulk: *vchiq.VchiqBulk, timeout_us: u64) u32 {
        return libraries.call(self, LVO.WaitBulk, Fn.WaitBulk, .{ bulk, timeout_us });
    }
};
